Content guardrail layer for the MLflow AI Gateway.

A :class:`JudgeGuardrail` wraps a scorer callable and runs it either before a request is
forwarded to a provider (``BEFORE``) or after a response is received (``AFTER``). Depending on
the configured action, a flagged payload is either rejected (``VALIDATION``) or rewritten by a
sanitization LLM (``SANITIZATION``).
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from typing import Any

from fastapi import HTTPException

from mlflow.entities.assessment import Feedback
from mlflow.entities.gateway_guardrail import GuardrailAction, GuardrailStage
from mlflow.gateway.providers.utils import send_request
from mlflow.types.chat import ChatCompletionRequest

_GATEWAY_URI_PREFIX = "gateway:/"
_OPENAI_URI_PREFIX = "openai:/"

_SANITIZATION_SYSTEM_PROMPT = (
    "You are a content sanitization service for an LLM gateway. The following chat completion "
    "payload was flagged by a guardrail. Rewrite it so that the flagged content is removed or "
    "neutralized while preserving the original intent as much as possible. Respond only with the "
    "sanitized payload as JSON conforming to the provided schema."
)


class GuardrailViolation(Exception):
    """Exception raised when a guardrail blocks a request or response.

    The error message contains the guardrail name and the scorer's rationale so that callers can
    surface why the payload was blocked.
    """


@dataclass
class _ScorerEvaluation:
    passing: bool
    rationale: str | None


def _is_passing_scalar(value: Any) -> bool:
    """Interpret a raw scalar scorer value as passing (True) or failing (False).

    ``bool`` is checked before ``str`` because ``bool`` is a subclass of ``int`` and a raw ``int``
    value is not a supported result type.
    """
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() == "yes"
    raise TypeError(f"unexpected value type for scorer result: {type(value).__name__}")


def _evaluate_scorer_result(result: Any) -> _ScorerEvaluation:
    """Reduce a scorer's return value to a pass/fail decision plus an optional rationale."""
    if isinstance(result, Feedback):
        return _ScorerEvaluation(_is_passing_scalar(result.value), result.rationale)
    if isinstance(result, list):
        for item in result:
            evaluation = _evaluate_scorer_result(item)
            if not evaluation.passing:
                return evaluation
        return _ScorerEvaluation(True, None)
    return _ScorerEvaluation(_is_passing_scalar(result), None)


class JudgeGuardrail:
    def __init__(
        self,
        scorer: Any,
        stage: GuardrailStage,
        action: GuardrailAction,
        name: str,
        action_llm_url: str = None,
        action_endpoint_name: str = None,
    ):
        self.scorer = scorer
        self.stage = stage
        self.action = action
        self.name = name
        self.action_llm_url = action_llm_url
        self.action_endpoint_name = action_endpoint_name

    async def process_request(self, request: dict) -> dict:
        if self.stage != GuardrailStage.BEFORE:
            return request
        result = self.scorer(inputs=request)
        return await self._apply_action(request, result)

    async def process_response(self, request: dict, response: dict) -> dict:
        if self.stage != GuardrailStage.AFTER:
            return response
        result = self.scorer(inputs=request, outputs=response)
        return await self._apply_action(response, result)

    async def _apply_action(self, payload: dict, result: Any) -> dict:
        evaluation = _evaluate_scorer_result(result)
        if evaluation.passing:
            return payload
        if self.action == GuardrailAction.VALIDATION:
            raise GuardrailViolation(self._violation_message(evaluation.rationale))
        return await self._sanitize(payload)

    def _violation_message(self, rationale: str | None) -> str:
        if rationale:
            return f"Guardrail '{self.name}' blocked the request: {rationale}"
        return f"Guardrail '{self.name}' blocked the request"

    async def _sanitize(self, payload: dict) -> dict:
        if self.action_llm_url is None:
            raise GuardrailViolation(
                f"Guardrail '{self.name}' flagged the payload but no action_llm_url is "
                "configured for sanitization"
            )

        request_payload = {
            "model": self.action_endpoint_name,
            "messages": [
                {"role": "system", "content": _SANITIZATION_SYSTEM_PROMPT},
                {"role": "user", "content": json.dumps(payload)},
            ],
            "response_format": {
                "type": "json_schema",
                "json_schema": {
                    "name": "sanitized_payload",
                    "strict": False,
                    "schema": ChatCompletionRequest.model_json_schema(),
                },
            },
        }

        try:
            response = await send_request(
                headers={},
                base_url=self.action_llm_url,
                path=f"gateway/{self.action_endpoint_name}/invocations",
                payload=request_payload,
            )
        except HTTPException as e:
            raise GuardrailViolation(
                f"Sanitization request failed for guardrail '{self.name}': {e.detail}"
            ) from e

        content = response["choices"][0]["message"]["content"]
        try:
            return json.loads(content)
        except (json.JSONDecodeError, TypeError) as e:
            raise GuardrailViolation(
                f"Sanitization LLM for guardrail '{self.name}' returned invalid JSON"
            ) from e

    @classmethod
    def from_entity(cls, entity: Any, server_url: str = None) -> JudgeGuardrail:
        from mlflow.genai.judges.instructions_judge import InstructionsJudge
        from mlflow.genai.scorers import Scorer

        scorer = Scorer.model_validate(entity.scorer.serialized_scorer)

        if entity.action_endpoint_name is not None:
            action_endpoint_name = entity.action_endpoint_name
            action_llm_url = server_url
        else:
            action_endpoint_name = None
            action_llm_url = None

        if isinstance(scorer, InstructionsJudge) and scorer.model.startswith(_GATEWAY_URI_PREFIX):
            scorer._model = _OPENAI_URI_PREFIX + scorer.model[len(_GATEWAY_URI_PREFIX) :]
            scorer._base_url = f"{server_url}/gateway/mlflow/v1/chat/completions"

        return cls(
            scorer=scorer,
            stage=entity.stage,
            action=entity.action,
            name=entity.name,
            action_llm_url=action_llm_url,
            action_endpoint_name=action_endpoint_name,
        )
